{
  "avaliacoes": [
    {
      "id": "E07a9266533b7be07",
      "pertinente": true,
      "tipo": "norma",
      "achados": [
        {
          "proposicao": "A fonte distingue equipamento de içamento, máquina de içamento e acessórios de içamento, situando lingas, manilhas e olhais como itens usados para conectar a máquina à carga.",
          "trechos": [
            "E07a9266533b7be07:0:693",
            "E07a9266533b7be07:693:1392"
          ],
          "condicoes": [
            "no contexto do documento de operações mecânicas e de guindaste offshore",
            "com base em definições e enquadramento regulatório estrangeiro"
          ],
          "limites": [
            "a fonte define categorias, mas não apresenta critérios de dimensionamento, ângulos de lingas ou distribuição de forças",
            "trata-se de referencial normativo estrangeiro, não de requisito brasileiro"
          ]
        },
        {
          "proposicao": "Acessórios de içamento devem ser armazenados em condições que evitem dano ou deterioração, relacionando compatibilidade operacional também ao controle de conservação do acessório antes do uso.",
          "trechos": [
            "E07a9266533b7be07:693:1392",
            "E07a9266533b7be07:1392:2092"
          ],
          "condicoes": [
            "no âmbito das exigências citadas de PUWER e LOLER",
            "aplicável ao gerenciamento e armazenamento de acessórios"
          ],
          "limites": [
            "não informa métodos específicos de armazenamento nem critérios de rejeição por tipo de acessório",
            "o enquadramento legal citado é estrangeiro"
          ]
        },
        {
          "proposicao": "A realização da operação de içamento em modo seguro inclui verificações pré-uso para identificar falhas ou danos em equipamentos e acessórios portáteis de içamento.",
          "trechos": [
            "E07a9266533b7be07:1392:2092"
          ],
          "condicoes": [
            "para operações envolvendo equipamento de içamento",
            "no contexto de gestão de equipamentos portáteis offshore"
          ],
          "limites": [
            "a fonte não detalha checklist técnico por acessório nesta passagem",
            "não apresenta limites de aceitação nem periodicidade universal aplicável fora do documento"
          ]
        }
      ]
    },
    {
      "id": "E892b30407726ed49",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Cargas longas, como tubulares, podem exigir um eslingador em cada extremidade para realizar conexão e desconexão, o que relaciona geometria da carga à configuração operacional do içamento.",
          "trechos": [
            "E892b30407726ed49:0:690"
          ],
          "condicoes": [
            "na prática offshore descrita para cargas longas",
            "durante operações com equipe de guindaste, banksman e slingers"
          ],
          "limites": [
            "a fonte descreve prática operacional, não critério universal de dimensionamento ou quantidade mínima para qualquer cenário",
            "não trata de seleção de vigas, manilhas, padeyes ou cálculo de esforços"
          ]
        },
        {
          "proposicao": "Duas ameaças principais à equipe em operações com guindaste são carga caída e carga oscilante, sendo a oscilação associada, entre outros fatores, a parada súbita, movimento do guindaste por estado do mar ou vento, erro do operador e liberação repentina da carga presa.",
          "trechos": [
            "E892b30407726ed49:690:1387"
          ],
          "condicoes": [
            "em operações offshore com guindaste",
            "na análise de perigos para pessoal envolvido"
          ],
          "limites": [
            "não quantifica estados ambientais, amplitudes de movimento ou limites operacionais",
            "o foco é consequência para segurança, não distribuição de forças entre acessórios"
          ]
        },
        {
          "proposicao": "A área abaixo da carga ou ao redor da trajetória possível de oscilação é tratada como zona de perigo, e quando não for praticável evitar içar sobre pessoas, devem existir medidas de proteção ou sistema de trabalho para exclusão de pessoas dessa zona.",
          "trechos": [
            "E892b30407726ed49:1387:1998"
          ],
          "condicoes": [
            "quando houver risco de queda ou oscilação da carga",
            "na condução de operações de içamento"
          ],
          "limites": [
            "a fonte não define distâncias, barreiras específicas ou critérios numéricos para delimitar a zona",
            "apresenta orientação de segurança de documento estrangeiro, não requisito brasileiro"
          ]
        }
      ]
    },
    {
      "id": "E18ac360c1b545c8d",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A condição de lingas de cabo de aço em uso, incluindo ausência de arames partidos e de dobras severas, aparece como aspecto de verificação operacional antes ou durante a atividade.",
          "trechos": [
            "E18ac360c1b545c8d:0:697"
          ],
          "condicoes": [
            "para lingas de cabo de aço observadas em uso",
            "no contexto de inspeção de operações de içamento"
          ],
          "limites": [
            "a fonte não fornece critério quantitativo de descarte nem classes de dano admissível",
            "não cobre outros materiais de lingas nesta passagem"
          ]
        },
        {
          "proposicao": "Cabos montados em guinchos devem ser observados quanto ao bom estado e ao enrolamento correto no tambor, sem acúmulo ou dobra severa, relacionando a condição do cabo ao comportamento seguro do sistema de içamento.",
          "trechos": [
            "E18ac360c1b545c8d:0:697"
          ],
          "condicoes": [
            "para cabos instalados em guinchos",
            "durante a verificação da operação"
          ],
          "limites": [
            "não descreve método de inspeção detalhado nem parâmetros de tensão ou enrolamento aceitáveis",
            "a passagem é checklist observacional, não ensaio experimental"
          ]
        },
        {
          "proposicao": "Manilhas observadas em uso devem estar com pinos providos do sistema correto de travamento, e a operação deve incluir inspeções pré-uso e aderência aos procedimentos escritos discutidos no toolbox talk.",
          "trechos": [
            "E18ac360c1b545c8d:0:697",
            "E18ac360c1b545c8d:697:1389"
          ],
          "condicoes": [
            "para manilhas efetivamente em uso na operação",
            "quando houver procedimentos escritos e discussão prévia da tarefa"
          ],
          "limites": [
            "a fonte não especifica quais sistemas de travamento são aceitáveis para cada manilha",
            "não informa frequência formal de inspeção nem critérios completos de rejeição"
          ]
        }
      ]
    },
    {
      "id": "E5e742c0332865a11",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Na análise preliminar de perigos apresentada, queda de objetos durante transporte e manuseio de carga é associada, entre outras causas, à ruptura de cabos e equipamentos e à má integridade de equipamentos de içamento.",
          "trechos": [
            "E5e742c0332865a11:1382:2081"
          ],
          "condicoes": [
            "no cenário hipotético de transporte e manuseio de carga descrito pela monografia",
            "como identificação de perigos e causas em HAZID/APR"
          ],
          "limites": [
            "é material de estudo acadêmico com cenário hipotético, não norma operacional consolidada",
            "não detalha mecanismos de falha por acessório nem critérios de seleção"
          ]
        },
        {
          "proposicao": "Como medidas de controle ou recomendações para esse perigo, a fonte lista certificação de equipamentos como eslingas e cabos, inspeção e manutenção preventiva, procedimento de movimentação de carga, sistema de comunicação e treinamento e competência.",
          "trechos": [
            "E5e742c0332865a11:1382:2081",
            "E5e742c0332865a11:2081:2376"
          ],
          "condicoes": [
            "no âmbito da análise preliminar de perigos da fonte",
            "para mitigação de queda de objetos em transporte e manuseio de carga"
          ],
          "limites": [
            "a fonte apresenta recomendações genéricas, sem definir periodicidades, critérios de certificação ou conteúdos mínimos",
            "não aborda diretamente distribuição de forças, ângulos de lingas ou padeyes"
          ]
        }
      ]
    },
    {
      "id": "E764705990c2a9d67",
      "pertinente": false,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "O trecho repete, no mesmo documento acadêmico, o conteúdo sobre queda de objetos e controles para equipamentos de içamento já presente em outra fonte correlata, sem acrescentar novo conhecimento específico sobre acessórios e distribuição de esforços.",
          "trechos": [
            "E764705990c2a9d67:0:698"
          ],
          "condicoes": [
            "comparado ao trecho correlato da mesma monografia"
          ],
          "limites": [
            "não deve ser tratado como estudo independente",
            "o valor para o recorte é redundante"
          ]
        }
      ]
    },
    {
      "id": "E74a3fa0216e24d58",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Na triagem e pré-embarque, a verificação das condições da carga inclui validade da eslinga e identificação do material antes de autorizar a movimentação.",
          "trechos": [
            "E74a3fa0216e24d58:0:695",
            "E74a3fa0216e24d58:695:1392"
          ],
          "condicoes": [
            "no fluxo operacional de pré-embarque descrito pelo sistema citado",
            "antes da autorização para movimentação da carga"
          ],
          "limites": [
            "não informa critérios técnicos de validade ou de rejeição da eslinga",
            "não detalha inspeção estrutural, compatibilidade ou capacidade do acessório"
          ]
        },
        {
          "proposicao": "O sistema de apoio ao embarque deve apontar quando peso ou volume máximo da embarcação for atingido e a taxa de ocupação, conectando planejamento logístico à decisão de quais cargas serão embarcadas.",
          "trechos": [
            "E74a3fa0216e24d58:1392:2092"
          ],
          "condicoes": [
            "no processo remodelado de movimentação interna de carga para embarque",
            "a partir da seleção de cargas e configuração da embarcação no sistema"
          ],
          "limites": [
            "o trecho trata de capacidade global de embarcação e ocupação, não da distribuição de forças em acessórios de içamento",
            "números de capacidade estão ausentes ou não recuperáveis"
          ]
        }
      ]
    }
  ],
  "concluir": false,
